  private async collectTree(rootDir: string, prefix: string): Promise<ZipEntry[]> {
    const out: ZipEntry[] = []
    const walk = async (dir: string, rel: string): Promise<void> => {
      const entries = await readdir(dir, { withFileTypes: true })
