src/client/index.ts.content:
/**
 * dsh-inspector 浏览器端插件。
 *
 * 职责:把手写的 projectFiles 调用描述符挂载到 ctx.remote($mount),
 * 注册 zh/en 词典到 ctx.locale,然后向两个 slot 注册 UI —— shell.overlay
 * 的右侧浮动面板,和 conversation.session.header.utilities 的开关按钮。
 * 两个注册都走 slots.inject:等 slot 声明方(ui-layout / ui-conversation)
 * 就绪后再注册,因此与其它插件可独立加载、也可合并加载,互不占用对方的
 * 座位;注册声明 locale: NS,框架把 t 标准位放进组件 props(locale 切换时
 * t 身份变化,组件随之重渲染)。
 */

import type {
  OverviewResult, ReadResult, RemoveResult, RpcOutcome, WriteResult,
} from '../scoped-files.js'
import { buildDescriptors } from './descriptors.js'
import { en, NS, zh } from './locales.js'
import { ProjectFilesPanel, ProjectFilesToggle, type ProjectFilesApi } from './panel.js'
import { createPanelStore } from './store.js'
import { ensureStyles } from './styles.js'
import type { ClientContext, RpcResult } from './types.js'

/** 需要的服务:remote 挂载面、会话列表快照、slot 注册面。 */
export const inject = ['remote', 'sessions', 'slots']

/** 解包 RPC 结果,失败转成 Error。 */
function unwrap<T>(result: RpcResult<T>): T {
  if (result.ok) return result.value
  throw new Error(`${result.error.code}: ${result.error.message}`)
}

/** 组装解包后的调用面。 */
function createApi(ctx: ClientContext): ProjectFilesApi {
  const calls = ctx.remote.projectFiles
  return {
    overview: async (cwd: string): Promise<RpcOutcome<OverviewResult>> => unwrap(await calls.overview(cwd)),
    readFile: async (cwd: string, scope: string, dir: string, name: string): Promise<RpcOutcome<ReadResult>> =>
      unwrap(await calls.readFile(cwd, scope, dir, name)),
    readSkillFile: async (cwd: string, root: string, skillPath: string): Promise<RpcOutcome<ReadResult>> =>
      unwrap(await calls.readSkillFile(cwd, root, skillPath)),
    writeSkillFile: async (cwd: string, root: string, skillPath: string, content: string): Promise<RpcOutcome<WriteResult>> =>
      unwrap(await calls.writeSkillFile(cwd, root, skillPath, content)),
    writeFile: async (cwd: string, scope: string, dir: string, name: string, content: string): Promise<RpcOutcome<WriteResult>> =>
      unwrap(await calls.writeFile(cwd, scope, dir, name, content)),
    removeFile: async (cwd: string, scope: string, dir: string, name: string): Promise<RpcOutcome<RemoveResult>> =>
      unwrap(await calls.removeFile(cwd, scope, dir, name)),
  }
}

/**
 * 插件主体:样式注入 → 挂载远端描述符 → 注册词典 → 注册面板与开关按钮。
 * @param ctx - 浏览器端 cordis 上下文。
 */
export async function apply(ctx: ClientContext): Promise<void> {
  ensureStyles()

  const disposeRemote = await ctx.remote.$mount({
    package: 'dsh-inspector',
    descriptors: buildDescriptors(),
  })
  ctx.effect(() => () => { void disposeRemote() }, 'dsh-inspector: remote descriptor mount')

  const store = createPanelStore()

  // 注册 zh/en 词典(动态 inject:locale 服务由宿主 dsh-client-locale 提供)。
  // 晚到注册会 bump revision,已挂载的出口随之取到词典。
  ctx.inject(['locale'], (localeCtx: ClientContext): void => {
    ctx.effect(() => {
      const dispose = localeCtx.locale.register(NS, { zh, en })
      return () => { if (typeof dispose === 'function') dispose() }
    }, 'dsh-inspector: register dictionaries')
  })

  // 远端命名空间服务 remote.projectFiles 由上面的 $mount 创建,不能写进静态
  // inject(那会在 apply 之前等待一个尚不存在的服务,永远挂起)。改用动态
  // inject:$mount 完成后命名空间已存在,回调立即触发,且回调上下文允许
  // 访问 ctx.remote.projectFiles。
  ctx.inject(['remote', 'remote.projectFiles'], (namespaceCtx: ClientContext): void => {
    const api = createApi(namespaceCtx)

    ctx.slots.inject('shell.overlay', () => ctx.slots.register({
      name: 'shell.overlay',
      id: 'dsh-inspector',
      order: 20,
      locale: NS,
      inject: (): Record<string, unknown> => ({ api, sessions: ctx.sessions, store }),
    }, ProjectFilesPanel))

    ctx.slots.inject('conversation.session.header.utilities', () => ctx.slots.register({
      name: 'conversation.session.header.utilities',
      id: 'dsh-inspector',
      order: 30,
      locale: NS,
      inject: (): Record<string, unknown> => ({ store }),
    }, ProjectFilesToggle))
  })
}

src/index.ts.content:
/**
 * dsh-inspector 宿主端:projectFiles 网关服务。
 *
 * 继承 TypertRemoteService 后,Typert Gateway 以 SRC 模式自动发现本服务;
 * 第三方双副本场景下 SRC 发现失明,因此同时把弱(src-json)清单注册进宿主
 * typert registry(见 TYPERT_MANIFEST 注释)。
 *
 * 语义:面板不再是「工作区根下白名单文件」的平铺列表,而是复刻 harness
 * dsh-agent-instructions 的真实指引链——全局 $DSH_HOME/AGENTS.md、项目根
 * (最近含 .git 的祖先)到会话 cwd 的每一级目录、每级 4 个候选文件——
 * 外加 dsh-skill-filesystem 的四个技能根目录状态。层级发现算法与 harness
 * 保持一字不差:.git 标记上溯、候选顺序、同目录 trimmed 内容去重、
 * 1MB 单文件上限。
 *
 * 路径安全:读写地址是「cwd + scope + dir + name」四元组。name 必须命中
 * 候选白名单;dir 必须命中按 cwd 现算出的项目链目录集合(global 层恒 '');
 * 最终路径 resolve 后再做前缀校验。目录(技能根)只在 overview 里展示状态,
 * 不接受内容读写。
 *
 * 失败协议:用户可见的失败不抛错(RPC 封套会把抛错塌缩成 internal + 裸
 * message,客户端拿不到结构化信息),而是以 FailureStatus 数据随结果返回:
 * 稳定点分 code(cwd.err.* / address.err.* / read.err.* …)+ 中文兜底文案
 * + 可选插值参数 + level:'error'。客户端按 code 查词典本地化,缺键退回
 * 中文兜底。可选字段条件展开(src-json codec 拒绝 undefined)。
 *
 * 重要:Gateway 通过 Function.prototype.toString 读取方法参数名作为
 * wire 字段名,因此本文件的公开方法必须保持「简单标识符参数」形态
 * (不解构、无默认值、无剩余参数),且构建产物不得压缩改写参数名。
 */

import { readFileSync, readdirSync, statSync, unlinkSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path'
import type { Context } from '@deepseek-ai/cordis'
import { Remote, TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'
import {
  ALL_CANDIDATES,
  BASE_CANDIDATES,
  LOCAL_CANDIDATES,
  MAX_SOURCE_BYTES,
  type FailureStatus,
  type InstructionFileMeta,
  type InstructionLayer,
  type OverviewResult,
  type ReadResult,
  type RemoveResult,
  type RpcOutcome,
  type SkillRootMeta,
  type WriteResult,
} from './scoped-files.js'

export type {
  FailureStatus,
  FileAddress,
  InstructionFileMeta,
  InstructionLayer,
  InstructionScope,
  OverviewResult,
  ReadResult,
  RemoveResult,
  RpcOutcome,
  SkillRootMeta,
  WriteResult,
} from './scoped-files.js'
export { ALL_CANDIDATES, BASE_CANDIDATES, LOCAL_CANDIDATES, MAX_SOURCE_BYTES } from './scoped-files.js'

/** 地址/校验解析结果:绝对路径,或失败状态。 */
type Resolved = string | FailureStatus

/** 构造一个失败状态(params 仅在给出时进入对象,src-json 拒绝 undefined)。 */
function failure(code: string, text: string, params?: Record<string, string>): FailureStatus {
  return { ok: false, code, text, level: 'error', ...(params !== undefined ? { params } : {}) }
}

/** 判定解析结果是否为失败状态。 */
function isFailure(value: Resolved): value is FailureStatus {
  return typeof value !== 'string'
}

/** 项目根标记(与 harness dsh-agent-instructions 默认 projectRootMarkers 一致)。 */
const PROJECT_ROOT_MARKERS = ['.git'] as const

/** 技能根目录数扫描的树深度与访问条目上限(防大目录拖慢 overview)。 */
const SKILL_SCAN_MAX_DEPTH = 4
const SKILL_SCAN_MAX_ENTRIES = 2000

/** 解析 dsh home($DSH_HOME 或 ~/.dsh,与 harness dsh-home-paths 一致)。 */
function dshHome(): string {
  const fromEnv = process.env.DSH_HOME
  if (fromEnv !== undefined && fromEnv.length > 0) return resolve(fromEnv)
  return join(homedir(), '.dsh')
}

/** 把绝对路径的 home 前缀替换为 ~(仅展示用)。 */
function tildeDisplay(path: string): string {
  const home = homedir()
  if (path === home) return '~'
  if (path.startsWith(home + sep)) return `~${path.slice(home.length)}`
  return path
}

/** 校验并解析工作区目录:必须是存在的绝对路径目录。 */
function checkCwd(cwd: string): Resolved {
  if (typeof cwd !== 'string' || cwd.length === 0 || cwd.includes('\0')) {
    return failure('cwd.err.type', 'projectFiles: cwd 必须是非空字符串')
  }
  if (!isAbsolute(cwd)) {
    return failure('cwd.err.relative', `projectFiles: cwd 必须是绝对路径,收到 ${JSON.stringify(cwd)}`, { received: JSON.stringify(cwd) })
  }
  let stats
  try {
    stats = statSync(cwd)
  } catch {
    return failure('cwd.err.inaccessible', `projectFiles: 工作区目录不可访问: ${cwd}`, { cwd })
  }
  if (!stats.isDirectory()) return failure('cwd.err.notDir', `projectFiles: cwd 不是目录: ${cwd}`, { cwd })
  return resolve(cwd)
}

/** 目录里是否存在项目根标记(文件或目录都算,与 harness existsAsMarker 一致)。 */
function hasMarker(dir: string): boolean {
  for (const marker of PROJECT_ROOT_MARKERS) {
    try {
      statSync(join(dir, marker))
      return true
    } catch { /* 标记缺失或不可读:视为不存在,继续上溯。 */ }
  }
  return false
}

/** 自 cwd 向上找最近含标记的目录;到文件系统根仍没有则返回 cwd 本身。 */
function findProjectRoot(cwd: string): string {
  let current = cwd
  for (;;) {
    if (hasMarker(current)) return current
    const parent = dirname(current)
    if (parent === current) return cwd
    current = parent
  }
}

/** 项目根 → cwd 的目录链(根相对路径,'' 为根;由宽到专)。 */
function chainDirs(projectRoot: string, cwd: string): string[] {
  const dirs: string[] = []
  let current = cwd
  while (current !== projectRoot) {
    dirs.push(relative(projectRoot, current))
    const parent = dirname(current)
    if (parent === current) break
    current = parent
  }
  dirs.push('')
  return dirs.reverse()
}

/** 文件统计,不存在返回 undefined。 */
function statOf(target: string): { size: number; mtimeIso: string } | undefined {
  try {
    const stats = statSync(target)
    if (!stats.isFile()) return undefined
    return { size: stats.size, mtimeIso: stats.mtime.toISOString() }
  } catch {
    return undefined
  }
}

/**
 * 探测一个目录的全部指引候选,并按 harness 的规则标注去重与超限。
 * @param dir - 探测的绝对目录。
 * @returns 4 个候选的状态(候选顺序)。
 */
function probeLayerFiles(dir: string): InstructionFileMeta[] {
  const metas: InstructionFileMeta[] = []
  // harness 的同目录去重键:去掉首尾空白后的全文;最先的候选保留。
  const keptDigests = new Map<string, string>()
  for (const name of ALL_CANDIDATES) {
    const target = join(dir, name)
    const stats = statOf(target)
    const local = (LOCAL_CANDIDATES as readonly string[]).includes(name)
    if (stats === undefined) {
      metas.push({ name, exists: false, size: 0, mtimeIso: '', local })
      continue
    }
    const oversized = stats.size > MAX_SOURCE_BYTES
    let duplicateOf: string | undefined
    if (!oversized) {
      try {
        const digest = readFileSync(target, 'utf8').trim()
        const kept = keptDigests.get(digest)
        if (kept === undefined) keptDigests.set(digest, name)
        else duplicateOf = kept
      } catch { /* 读取瞬时失败:跳过去重标注,存在性照常展示。 */ }
    }
    metas.push({
      name,
      exists: true,
      size: stats.size,
      mtimeIso: stats.mtimeIso,
      local,
      ...duplicateOf !== undefined ? { duplicateOf } : {},
      ...oversized ? { oversized: true } : {},
    })
  }
  return metas
}

/** 读一个 SKILL.md 的 frontmatter name(限量读取;失败回退目录名)。 */
function skillNameOf(skillMd: string, fallback: string): string {
  try {
    const head = readFileSync(skillMd, 'utf8').slice(0, 2048)
    const match = /^name:\s*(.+)$/m.exec(head)
    if (match !== null) {
      const value = match[1]!.trim().replace(/^["']|["']$/g, '')
      if (value !== '') return value
    }
  } catch { /* 读不到就用目录名 */ }
  return fallback
}

/** 收集一个技能根目录树内的技能(SKILL.md 目录 + 根层平铺 .md;限深限量)。 */
function collectSkills(root: string): { name: string; path: string }[] {
  const out: { name: string; path: string }[] = []
  let visited = 0
  const walk = (dir: string, rel: string, depth: number): void => {
    if (depth > SKILL_SCAN_MAX_DEPTH || visited > SKILL_SCAN_MAX_ENTRIES || out.length >= 100) return
    let entries
    try {
      entries = readdirSync(dir, { withFileTypes: true })
    } catch {
      return
    }
    for (const entry of entries) {
      visited += 1
      if (visited > SKILL_SCAN_MAX_ENTRIES || out.length >= 100) return
      const relPath = rel === '' ? entry.name : `${rel}/${entry.name}`
      if (entry.isFile() && entry.name === 'SKILL.md') {
        out.push({ name: skillNameOf(join(dir, entry.name), dir.split('/').pop() ?? 'skill'), path: relPath })
      } else if (depth === 0 && entry.isFile() && entry.name.endsWith('.md')) {
        out.push({ name: entry.name.slice(0, -3), path: relPath })
      } else if (entry.isDirectory()) {
        walk(join(dir, entry.name), relPath, depth + 1)
      }
    }
  }
  walk(root, '', 0)
  return out.sort((a, b) => a.name.localeCompare(b.name))
}

/** 一个技能根的状态行。 */
function skillRootMeta(path: string, displayPath: string, level: 'project' | 'user'): SkillRootMeta {
  let exists = false
  try {
    exists = statSync(path).isDirectory()
  } catch { /* 不存在或不可读:按不存在展示。 */ }
  if (!exists) return { displayPath, level, exists }
  const skills = collectSkills(path)
  return { displayPath, level, exists, skillCount: skills.length, skills }
}

/** 弱(src-json)调用描述符:参数与结果都按 JSON 原样过wire,不做 zod 校验。 */
interface WeakInvocation {
  readonly id: string
  readonly service: 'projectFiles'
  readonly namespace: 'projectFiles'
  readonly method: string
  readonly invocation: { readonly kind: 'direct' }
  readonly parameters: ReadonlyArray<{
    readonly name: string
    readonly wire: string
    readonly source: 'json'
    readonly codec: { readonly mode: 'src-json' }
  }>
  readonly result: { readonly mode: 'src-json' }
}

/** ctx.typert 注册面(宿主 dsh-typert-registry 提供;本包不依赖其类型)。 */
interface TypertRegistryLike {
  register(contribution: unknown): unknown
}

function jsonParameter(name: string): WeakInvocation['parameters'][number] {
  return { name, wire: name, source: 'json', codec: { mode: 'src-json' } }
}

function invocation(method: string, parameters: readonly string[]): WeakInvocation {
  return {
    id: `dsh-inspector#projectFiles/${method}`,
    service: 'projectFiles',
    namespace: 'projectFiles',
    method,
    invocation: { kind: 'direct' },
    parameters: parameters.map(jsonParameter),
    result: { mode: 'src-json' },
  }
}

/**
 * 宿主端弱类型 TYPERT 清单:把 projectFiles/* 端点作为 strict 定义注册进
 * 宿主的 typert registry。
 *
 * 为什么必须走注册而不能只靠 @Remote/SRC 发现:第三方插件解析到自己
 * node_modules 里的 @deepseek-ai/dsh-typert-protocol 副本,装饰器标记写进
 * 那份副本的模块私有 WeakMap;宿主 Gateway 用的是宿主侧另一份副本,
 * remoteMethods 读不到任何标记,SRC 发现会得到 0 个端点(浏览器里
 * projectFiles/* 全部 404)。清单是纯数据,跨副本可见,Gateway 的
 * strict 定义路径直接命中。官方 registry 明确保留手动
 * ctx.typert.register() 给无 ./typert 构件的贡献。
 */
const TYPERT_MANIFEST = {
  package: 'dsh-inspector',
  face: 'host',
  schemas: [],
  model: { services: [], events: [], objects: [] },
  invocations: [
    invocation('overview', ['cwd']),
    invocation('readFile', ['cwd', 'scope', 'dir', 'name']),
    invocation('readSkillFile', ['cwd', 'root', 'skillPath']),
    invocation('writeSkillFile', ['cwd', 'root', 'skillPath', 'content']),
    invocation('writeFile', ['cwd', 'scope', 'dir', 'name', 'content']),
    invocation('removeFile', ['cwd', 'scope', 'dir', 'name']),
  ] satisfies WeakInvocation[],
} as const

/**
 * projectFiles 网关服务:当前会话指引链(全局 + 项目链)的概览/读取/写入/删除,
 * 以及技能根目录状态。
 * @param ctx - 宿主 Cordis 上下文。
 */
export class ProjectFilesGateway extends TypertRemoteService {
  /** 注册 'projectFiles' 服务键;typert registry 就绪后补登记弱清单。 */
  constructor(ctx: Context) {
    super(ctx, 'projectFiles')
    // 动态 inject:typert 不在场的组合(如 ACP 示例配置)里静默跳过,
    // 不阻塞 boot;register 返回的 disposer 作为回调返回值参与卸载。
    ctx.inject(['typert'], (typertCtx: Context) =>
      (typertCtx as unknown as { typert: TypertRegistryLike }).typert.register(TYPERT_MANIFEST))
  }

  /** 解析一个读写地址为绝对路径(校验 scope/dir/name 全部命中白名单)。 */
  private resolveAddress(cwd: string, scope: string, dir: string, name: string): Resolved {
    const resolvedCwd = checkCwd(cwd)
    if (isFailure(resolvedCwd)) return resolvedCwd
    if (typeof name !== 'string' || !ALL_CANDIDATES.includes(name)) {
      return failure('address.err.name', `projectFiles: 不支持的指引文件名: ${JSON.stringify(name)}`, { name: JSON.stringify(name) })
    }
    if (scope === 'global') {
      if (name !== 'AGENTS.md') {
        return failure('address.err.globalName', 'projectFiles: 全局层只有 AGENTS.md')
      }
      return join(dshHome(), 'AGENTS.md')
    }
    if (scope !== 'project') {
      return failure('address.err.scope', `projectFiles: 不支持的层: ${JSON.stringify(scope)}`, { scope: JSON.stringify(scope) })
    }
    if (typeof dir !== 'string' || dir.includes('\0')) {
      return failure('address.err.dir', 'projectFiles: dir 必须是字符串')
    }
    const projectRoot = findProjectRoot(resolvedCwd)
    if (!chainDirs(projectRoot, resolvedCwd).includes(dir)) {
      return failure('address.err.offChain', `projectFiles: 目录不在当前会话的指引链上: ${JSON.stringify(dir)}`, { dir: JSON.stringify(dir) })
    }
    const target = resolve(projectRoot, dir, name)
    // dir 来自现算的链、name 来自固定字面量白名单;前缀校验是纵深防御。
    if (!target.startsWith(projectRoot + sep)) {
      return failure('address.err.escape', 'projectFiles: 解析后的路径越出了项目根')
    }
    return target
  }

  /** 当前会话的完整指引链概览:全局层、项目链每级候选状态、技能根状态。 */
  @Remote
  overview(cwd: string): RpcOutcome<OverviewResult> {
    const resolvedCwd = checkCwd(cwd)
    if (isFailure(resolvedCwd)) return resolvedCwd
    const projectRoot = findProjectRoot(resolvedCwd)
    const home = dshHome()

    const layers: InstructionLayer[] = [{
      scope: 'global',
      dir: '',
      displayDir: tildeDisplay(home),
      isCwd: false,
      // 全局层只认 AGENTS.md(harness USER_GLOBAL_FILE),不探测其余候选。
      files: probeLayerFiles(home).filter(meta => meta.name === 'AGENTS.md'),
    }]
    for (const dir of chainDirs(projectRoot, resolvedCwd)) {
      const absolute = resolve(projectRoot, dir)
      layers.push({
        scope: 'project',
        dir,
        displayDir: dir === '' ? tildeDisplay(projectRoot) : dir,
        isCwd: absolute === resolvedCwd,
        files: probeLayerFiles(absolute),
      })
    }

    const agentsHome = join(homedir(), '.agents')
    const skills: SkillRootMeta[] = [
      skillRootMeta(join(projectRoot, '.dsh/skills'), '.dsh/skills', 'project'),
      skillRootMeta(join(projectRoot, '.agents/skills'), '.agents/skills', 'project'),
      skillRootMeta(join(home, 'skills'), `${tildeDisplay(home)}/skills`, 'user'),
      skillRootMeta(join(agentsHome, 'skills'), `${tildeDisplay(agentsHome)}/skills`, 'user'),
    ]

    return {
      cwd: resolvedCwd,
      projectRoot,
      cwdRel: relative(projectRoot, resolvedCwd),
      layers,
      skills,
    }
  }

  /** 按 overview 的 displayPath 解析技能根的绝对路径(限四个已知根)。 */
  private resolveSkillRoot(cwd: string, root: string): Resolved {
    const resolvedCwd = checkCwd(cwd)
    if (isFailure(resolvedCwd)) return resolvedCwd
    const projectRoot = findProjectRoot(resolvedCwd)
    const home = dshHome()
    const agentsHome = join(homedir(), '.agents')
    const roots = new Map<string, string>([
      ['.dsh/skills', join(projectRoot, '.dsh/skills')],
      ['.agents/skills', join(projectRoot, '.agents/skills')],
      [`${tildeDisplay(home)}/skills`, join(home, 'skills')],
      [`${tildeDisplay(agentsHome)}/skills`, join(agentsHome, 'skills')],
    ])
    const absolute = roots.get(root)
    if (absolute === undefined) {
      return failure('skillRoot.err.unsupported', `projectFiles: 不支持的技能根: ${JSON.stringify(root)}`, { root: JSON.stringify(root) })
    }
    return absolute
  }

  /** 解析技能文件地址(root 相对路径,必须命中 .md 且不越根)。 */
  private resolveSkillFile(cwd: string, root: string, skillPath: string): Resolved {
    if (typeof skillPath !== 'string' || skillPath.includes('\0') || skillPath.includes('..') || isAbsolute(skillPath) || !skillPath.endsWith('.md')) {
      return failure('skillFile.err.path', `projectFiles: 不支持的技能文件路径: ${JSON.stringify(skillPath)}`, { path: JSON.stringify(skillPath) })
    }
    const rootAbs = this.resolveSkillRoot(cwd, root)
    if (isFailure(rootAbs)) return rootAbs
    const target = resolve(rootAbs, skillPath)
    if (!target.startsWith(rootAbs + sep)) {
      return failure('skillFile.err.escape', 'projectFiles: 解析后的路径越出了技能根')
    }
    return target
  }

  /** 读取一个技能文件(SKILL.md/平铺 .md)的全文与元信息。 */
  readSkillFile(cwd: string, root: string, skillPath: string): RpcOutcome<ReadResult> {
    const target = this.resolveSkillFile(cwd, root, skillPath)
    if (isFailure(target)) return target
    const stats = statOf(target)
    if (stats === undefined) return failure('readSkill.err.missing', `projectFiles: 技能文件不存在: ${skillPath}`, { path: skillPath })
    return { content: readFileSync(target, 'utf8'), size: stats.size, mtimeIso: stats.mtimeIso }
  }

  /** 写入一个技能文件(字节原样;经符号链接写穿到来源)。 */
  writeSkillFile(cwd: string, root: string, skillPath: string, content: string): RpcOutcome<WriteResult> {
    const target = this.resolveSkillFile(cwd, root, skillPath)
    if (isFailure(target)) return target
    if (typeof content !== 'string') return failure('write.err.content', 'projectFiles: content 必须是字符串')
    writeFileSync(target, content, 'utf8')
    const stats = statOf(target)
    if (stats === undefined) return failure('writeSkill.err.stat', `projectFiles: 写入后无法读取状态: ${skillPath}`, { path: skillPath })
    return { size: stats.size, mtimeIso: stats.mtimeIso }
  }

  /** 读取指引链上一个文件的全文与元信息。 */
  @Remote
  readFile(cwd: string, scope: string, dir: string, name: string): RpcOutcome<ReadResult> {
    const target = this.resolveAddress(cwd, scope, dir, name)
    if (isFailure(target)) return target
    const stats = statOf(target)
    if (stats === undefined) return failure('read.err.missing', `projectFiles: 文件不存在: ${name}`, { name })
    return { content: readFileSync(target, 'utf8'), size: stats.size, mtimeIso: stats.mtimeIso }
  }

  /** 写入(新建或覆盖)指引链上一个文件,返回写入后的元信息。 */
  @Remote
  writeFile(cwd: string, scope: string, dir: string, name: string, content: string): RpcOutcome<WriteResult> {
    const target = this.resolveAddress(cwd, scope, dir, name)
    if (isFailure(target)) return target
    if (typeof content !== 'string') return failure('write.err.content', 'projectFiles: content 必须是字符串')
    writeFileSync(target, content, 'utf8')
    const stats = statOf(target)
    if (stats === undefined) return failure('write.err.stat', `projectFiles: 写入后无法读取状态: ${name}`, { name })
    return { size: stats.size, mtimeIso: stats.mtimeIso }
  }

  /** 删除指引链上一个文件;文件本就不存在时 removed 为 false。命名为 removeFile:客户端命名空间服务的原型上已占用 remove。 */
  @Remote
  removeFile(cwd: string, scope: string, dir: string, name: string): RpcOutcome<RemoveResult> {
    const target = this.resolveAddress(cwd, scope, dir, name)
    if (isFailure(target)) return target
    if (statOf(target) === undefined) return { removed: false }
    unlinkSync(target)
    return { removed: true }
  }
}

export default ProjectFilesGateway
